var run=UnityEngine.Object.FindFirstObjectByType<ArmySurvivor.Army.RunController>();
var rec=UnityEngine.Object.FindFirstObjectByType<ArmySurvivor.Army.RecruitmentController>();
var combat=UnityEngine.Object.FindFirstObjectByType<ArmySurvivor.Army.CombatController>();
var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
var sb=new System.Text.StringBuilder();
var pos=run.Commander.position;run.Tick(UnityEngine.Vector2.one,0.1f);if(run.Commander.position!=pos)throw new System.Exception("Dead commander moved");
combat.Tick(0.1f);if(!run.IsRunning)throw new System.Exception("Death was cut short");
run.ReturnToPreparation();
foreach(var unit in rec.Units.Keys)foreach(var a in unit.GetComponentsInChildren<UnityEngine.Animator>())if(a.GetCurrentAnimatorStateInfo(0).IsName("Death"))throw new System.Exception("Did not reset "+unit.name);
sb.AppendLine("Death holds; dead commander cannot move; preparation restores idle.");
run.BeginRun();foreach(var unit in rec.Units.Keys)unit.position=run.Commander.position+UnityEngine.Vector3.right*20;
var definition=UnityEditor.AssetDatabase.LoadAssetAtPath<ArmySurvivor.Army.EnemyDefinition>("Assets/CombatData/Orc.asset");
var spawn=typeof(ArmySurvivor.Army.CombatController).GetMethod("Spawn",flags,null,new[]{typeof(ArmySurvivor.Army.EnemyDefinition),typeof(bool)},null);spawn.Invoke(combat,new object[]{definition,false});
var list=(System.Collections.IList)typeof(ArmySurvivor.Army.CombatController).GetField("enemies",flags).GetValue(combat);var state=list[0];var st=state.GetType();
var root=(UnityEngine.Transform)st.GetField("root").GetValue(state);root.position=run.Commander.position+UnityEngine.Vector3.forward*definition.stoppingDistance;
var anim=(UnityEngine.Animator)st.GetField("animator").GetValue(state);
var move=typeof(ArmySurvivor.Army.CombatController).GetMethod("MoveEnemies",flags);
var health=run.Commander.GetComponent<ArmySurvivor.Army.UnitHealth>();float before=health.Current;
move.Invoke(combat,new object[]{0.01f});anim.Update(0);if(!anim.GetCurrentAnimatorStateInfo(0).IsName("Attack"))throw new System.Exception("No attack animation");
move.Invoke(combat,new object[]{0.2f});if(health.Current!=before)throw new System.Exception("Early damage");
move.Invoke(combat,new object[]{0.16f});float after=health.Current;if(after>=before)throw new System.Exception("No damage");
move.Invoke(combat,new object[]{0.1f});if(health.Current!=after)throw new System.Exception("Double damage");
sb.AppendLine("Orc Attack: damage after windup only, once per swing: "+before+" -> "+after);
var hit=typeof(ArmySurvivor.Army.CombatController).GetMethod("ApplyDamage",flags);hit.Invoke(combat,new object[]{state,99999f,UnityEngine.Vector3.forward,0f});anim.Update(0.4f);
if(!anim.GetCurrentAnimatorStateInfo(0).IsName("Death"))throw new System.Exception("Orc death failed");
move.Invoke(combat,new object[]{0.4f});if(health.Current!=after)throw new System.Exception("Dead orc attacked");
sb.AppendLine("Orc death interrupts attack; no damage after death.");
health.TakeDamage(999999);combat.Tick(0.1f);if(!run.IsRunning)throw new System.Exception("Commander death cut short");
typeof(ArmySurvivor.Army.UnitHealth).GetField("deathEndsAt",flags).SetValue(health,UnityEngine.Time.time-1);combat.Tick(0.1f);
if(run.IsRunning||health.IsDead)throw new System.Exception("Commander return/reset failed");
sb.AppendLine("Commander returns only after death duration and revives for preparation.");
return sb.ToString();
